SELECT gen_random_uuid()::text, 'formula', '$\lfloor q_i \rfloor$', 'Hamilton''s Method', '$\text{give } \lfloor q_i \rfloor, \text{ then the leftover seats one each to the largest fractional parts}$', NULL, 'Apportion by lower quotas, then hand out the remaining seats by largest remainder.', '[{"symbol":"$q_i$","meaning":"the standard quotas"}]'::jsonb, 'It always meets quota, but can suffer the Alabama paradox (more seats, a state loses one).', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Math in the Modern World' AND t."subject" = 'Mathematics' AND s."normKey" = 'apportionment and voting' AND s."active"), NULL, true, 'PENDING', now(), now()
