SELECT gen_random_uuid()::text, 'formula', '$d'' < d$', 'Jefferson''s Method', '$\text{find } d'' \text{ with } \sum \left\lfloor \frac{p_i}{d''} \right\rfloor = \text{seats}$', NULL, 'Round every modified quota down, adjusting the divisor until the seats add up.', '[{"symbol":"$d''$","meaning":"a modified divisor, smaller than the standard one"}]'::jsonb, 'It favours large states.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Math in the Modern World' AND t."subject" = 'Mathematics' AND s."normKey" = 'apportionment and voting' AND s."active"), NULL, true, 'PENDING', now(), now()
