SELECT gen_random_uuid()::text, 'formula', '$\sqrt{n(n + 1)}$', 'Huntington-Hill Method', '$\text{round } q_i \text{ up when } q_i \ge \sqrt{n(n + 1)},\ n = \lfloor q_i \rfloor; \text{ adjust } d'' \text{ until the seats add up}$', NULL, 'Like Webster''s, but the cut-off for rounding up is the geometric mean of n and n + 1.', '[{"symbol":"$n$","meaning":"the lower quota"}]'::jsonb, 'For 2.45: cut-off $\sqrt{6} = 2.449$, so it rounds UP to 3.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Math in the Modern World' AND t."subject" = 'Mathematics' AND s."normKey" = 'apportionment and voting' AND s."active"), NULL, true, 'PENDING', now(), now()
