SELECT gen_random_uuid()::text, 'formula', '$C(n, 2)$', 'Number of Pairwise Comparisons', '$C(n, 2) = \frac{n(n - 1)}{2}$', NULL, 'The head-to-head contests needed to compare every pair of candidates.', '[{"symbol":"$n$","meaning":"the number of candidates"}]'::jsonb, 'Each win scores 1, each tie ½; 5 candidates need 10 comparisons.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Math in the Modern World' AND t."subject" = 'Mathematics' AND s."normKey" = 'apportionment and voting' AND s."active"), NULL, true, 'PENDING', now(), now()
