SELECT gen_random_uuid()::text, 'formula', '$\lfloor V/2 \rfloor + 1$', 'Majority Threshold', '$\text{majority} = \left\lfloor \frac{V}{2} \right\rfloor + 1 \text{ votes};\quad \text{plurality} = \text{the most votes}$', NULL, 'A majority is more than half the votes; a plurality is simply the most.', '[{"symbol":"$V$","meaning":"the number of votes cast"}]'::jsonb, 'A candidate with a majority of first places wins under plurality, but may lose a Borda count.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Math in the Modern World' AND t."subject" = 'Mathematics' AND s."normKey" = 'apportionment and voting' AND s."active"), NULL, true, 'PENDING', now(), now()
