SELECT gen_random_uuid()::text, 'formula', '$\sum \deg(v)$', 'Handshaking Lemma', '$\sum_{v} \deg(v) = 2|E|$', NULL, 'Each edge adds 2 to the total degree, so the degrees add to twice the edges.', '[{"symbol":"$\\deg(v)$","meaning":"the number of edges at vertex v"},{"symbol":"$|E|$","meaning":"the number of edges"}]'::jsonb, 'So every graph has an even number of odd-degree vertices.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Math in the Modern World' AND t."subject" = 'Mathematics' AND s."normKey" = 'graph theory' AND s."active"), NULL, true, 'PENDING', now(), now()
