SELECT gen_random_uuid()::text, 'formula', '$(n - 1)!$', 'Hamilton Circuits in a Complete Graph', '$(n - 1)! \text{ circuits};\quad \frac{(n - 1)!}{2} \text{ if a circuit and its reverse count once}$', NULL, 'The number of routes visiting every vertex once and returning (the travelling salesman''s choices).', '[{"symbol":"$n$","meaning":"the vertices"}]'::jsonb, 'They grow so fast that brute force fails beyond about 10 cities: use nearest-neighbour or cheapest-edge.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Math in the Modern World' AND t."subject" = 'Mathematics' AND s."normKey" = 'graph theory' AND s."active"), NULL, true, 'PENDING', now(), now()
