SELECT gen_random_uuid()::text, 'formula', '$|E| = n - 1$', 'Edges of a Tree', '$\text{a tree on } n \text{ vertices has } n - 1 \text{ edges and no circuits}$', NULL, 'A connected graph with no circuits; a spanning tree reaches every vertex of a network.', '[{"symbol":"$n$","meaning":"the vertices"}]'::jsonb, 'Kruskal''s algorithm builds a minimum spanning tree by adding the cheapest edge that makes no circuit.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Math in the Modern World' AND t."subject" = 'Mathematics' AND s."normKey" = 'graph theory' AND s."active"), NULL, true, 'PENDING', now(), now()
