SELECT gen_random_uuid()::text, 'formula', '$V - E + F = 2$', 'Euler Formula for Planar Graphs', '$V - E + F = 2$', NULL, 'For a connected graph drawn in the plane without crossings.', '[{"symbol":"$V, E, F$","meaning":"vertices, edges and faces, counting the outer face"}]'::jsonb, 'Planar graphs also have $E \le 3V - 6$ (for $V \ge 3$): $K_5$ breaks it, so it isn''t planar.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Math in the Modern World' AND t."subject" = 'Mathematics' AND s."normKey" = 'graph theory' AND s."active"), NULL, true, 'PENDING', now(), now()
